tool_schemas.implementation:
def get_monitors(workspace_id, group_states=None, tags=None, monitor_tags=None, limit=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0064000" if __import__("os").path.isdir("./environment_mix/0064000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.now(datetime.timezone.utc)
    _now_iso = _now.isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _cleanup_expired(workspace, assets, results):
        # Deletes expired cached objects/results for this workspace based on expires_at.
        changed_assets = False
        changed_results = False
        for coll, flag in (("assets", True), ("results", True)):
            pass
        w_id = workspace["id"]
        new_assets = []
        for a in assets:
            if a.get("workspace_id") != w_id:
                new_assets.append(a)
                continue
            ex = _parse_dt(a.get("expires_at"))
            if ex is not None and ex <= _now:
                changed_assets = True
                continue
            new_assets.append(a)
        new_results = []
        for r in results:
            if r.get("workspace_id") != w_id:
                new_results.append(r)
                continue
            ex = _parse_dt(r.get("expires_at"))
            if ex is not None and ex <= _now:
                changed_results = True
                continue
            new_results.append(r)
        return new_assets, new_results, changed_assets, changed_results

    def _gen_id(prefix):
        # Matches ddw_ pattern style; for other tables use simple prefixes.
        # 20 chars of base32-ish from uuid hex upper.
        tok = uuid.uuid4().hex.upper()
        return f"{prefix}_{tok[:22]}"

    def _log_call(request_workspace_id, resolved_workspace_id, status, credential_id=None, error_code=None, error_message=None, meta=None):
        # Use query_jobs as the request/audit log for this surface.
        qjobs = _load("query_jobs.json")
        job_id = _gen_id("ddqj")
        row = {
            "id": job_id,
            "workspace_id": resolved_workspace_id or request_workspace_id,
            "tool_name": "get-monitors",
            "request_params": {
                "workspace_id": request_workspace_id,
                "group_states": group_states,
                "tags": tags,
                "monitor_tags": monitor_tags,
                "limit": limit,
            },
            "filter_query": None,
            "from_time": None,
            "to_time": None,
            "sort": None,
            "limit": limit,
            "group_states": group_states,
            "tags": tags,
            "monitor_tags": monitor_tags,
            "aggregation": None,
            "status": status,
            "error_message": error_message if status in ("failed", "cancelled") else None,
            "datadog_request_id": None,
            "started_at": _now_iso,
            "finished_at": _now_iso,
            "created_at": _now_iso,
            "updated_at": _now_iso,
        }
        if meta:
            row["request_params"]["_meta"] = meta
        qjobs.append(row)
        _save("query_jobs.json", qjobs)
        return job_id

    # ---- Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^ddw_[0-9A-Z]{18,}$", workspace_id):
        _log_call(workspace_id, None, "failed", error_code="VALIDATION_ERROR", error_message="workspace_id is invalid")
        return _err("VALIDATION_ERROR", "workspace_id is invalid", field="workspace_id")

    def _validate_str_array(val, field):
        if val is None:
            return None
        if not isinstance(val, list) or any(not isinstance(x, str) for x in val):
            return _err("VALIDATION_ERROR", f"{field} must be an array of strings", field=field)
        return None

    if group_states is not None:
        if not isinstance(group_states, list) or any(not isinstance(x, str) for x in group_states):
            _log_call(workspace_id, workspace_id, "failed", error_code="VALIDATION_ERROR", error_message="group_states must be an array of strings")
            return _err("VALIDATION_ERROR", "group_states must be an array of strings", field="group_states")
        allowed = {"alert", "warn", "no_data", "ok"}
        normalized = []
        for s in group_states:
            # Tool schema already uses no_data, but business rule mentions normalizing 'no data'
            ss = s.strip().lower().replace(" ", "_")
            if ss == "no_data":
                pass
            if ss not in allowed:
                _log_call(workspace_id, workspace_id, "failed", error_code="VALIDATION_ERROR", error_message=f"Unknown group state: {s}")
                return _err("VALIDATION_ERROR", f"Unknown group state: {s}", field="group_states", allowed=sorted(list(allowed)))
            normalized.append(ss)
        group_states = normalized

    e = _validate_str_array(tags, "tags")
    if e:
        _log_call(workspace_id, workspace_id, "failed", error_code=e["error"]["code"], error_message=e["error"]["message"])
        return e
    e = _validate_str_array(monitor_tags, "monitor_tags")
    if e:
        _log_call(workspace_id, workspace_id, "failed", error_code=e["error"]["code"], error_message=e["error"]["message"])
        return e

    if limit is not None:
        if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1:
            _log_call(workspace_id, workspace_id, "failed", error_code="VALIDATION_ERROR", error_message="limit must be an integer >= 1")
            return _err("VALIDATION_ERROR", "limit must be an integer >= 1", field="limit")

    # ---- Resolve workspace + credential prerequisites
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _log_call(workspace_id, None, "failed", error_code="NOT_FOUND", error_message="Workspace not found")
        return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)

    creds = _load("api_credentials.json")
    active_cred = next((c for c in creds if c.get("workspace_id") == workspace_id and c.get("status") == "active"), None)

    # Business rule: workspace status != active must not execute tools that call Datadog; fail with actionable error and create failed job.
    # These tools read cached assets, but still require a connected/active workspace per tool description.
    if ws.get("status") != "active" or not active_cred:
        msg = "Workspace is not connected/active for Datadog requests"
        job_id = _log_call(workspace_id, workspace_id, "failed", credential_id=(active_cred or {}).get("id"), error_code="UNAUTHORIZED", error_message=msg)
        return _err("UNAUTHORIZED", msg, workspace_status=ws.get("status"), query_job_id=job_id)

    # ---- Enforce retention cleanup before fulfilling
    assets = _load("datadog_assets.json")
    results = _load("query_results.json")
    assets2, results2, ch_a, ch_r = _cleanup_expired(ws, assets, results)
    if ch_a:
        _save("datadog_assets.json", assets2)
        assets = assets2
    if ch_r:
        _save("query_results.json", results2)
        results = results2

    # ---- Apply defaults
    eff_limit = limit if limit is not None else ws.get("default_result_limit")
    if not isinstance(eff_limit, int) or eff_limit < 1:
        job_id = _log_call(workspace_id, workspace_id, "failed", credential_id=active_cred.get("id"), error_code="VALIDATION_ERROR", error_message="Resolved limit is invalid")
        return _err("VALIDATION_ERROR", "Resolved limit is invalid", field="limit", query_job_id=job_id)
    if eff_limit > 1000:
        eff_limit = 1000

    # ---- Query cached monitors
    rows = [a for a in assets if a.get("workspace_id") == workspace_id and a.get("asset_type") == "monitor"]

    # group_states: match against cached 'state' field (internal values are already underscore)
    if group_states:
        gs = set(group_states)
        rows = [a for a in rows if (a.get("state") in gs)]

    # tags: require all provided tags present in asset.tags
    if tags:
        want = [t for t in tags if t != ""]
        if want:
            def _has_all_tags(asset_tags):
                if not isinstance(asset_tags, list):
                    return False
                aset = set(str(x) for x in asset_tags)
                return all(t in aset for t in want)
            rows = [a for a in rows if _has_all_tags(a.get("tags"))]

    # monitor_tags: treat as additional required tags (best-effort interpretation)
    if monitor_tags:
        want2 = [t for t in monitor_tags if t != ""]
        if want2:
            def _has_all_tags2(asset_tags):
                if not isinstance(asset_tags, list):
                    return False
                aset = set(str(x) for x in asset_tags)
                return all(t in aset for t in want2)
            rows = [a for a in rows if _has_all_tags2(a.get("tags"))]

    total = len(rows)
    rows = rows[:eff_limit]

    # ---- Create job + result snapshot (must always create one job; on success must write exactly one result)
    job_id = None
    try:
        job_id = _log_call(workspace_id, workspace_id, "succeeded", credential_id=active_cred.get("id"))
    except Exception:
        # last resort: tool must not raise
        return _err("CONFLICT", "Failed to record query job")

    # Write result row
    retention_days = ws.get("result_retention_days")
    if not isinstance(retention_days, int) or retention_days < 1:
        retention_days = 1
    expires_at = (_now + datetime.timedelta(days=retention_days)).isoformat()

    qres = _load("query_results.json")
    # enforce unique(query_job_id): do not create if already exists (shouldn't)
    if any(r.get("query_job_id") == job_id for r in qres):
        return _err("CONFLICT", "Query result already exists for this job", query_job_id=job_id)

    res_row = {
        "id": _gen_id("ddqr"),
        "query_job_id": job_id,
        "workspace_id": workspace_id,
        "result_kind": "monitors",
        "items": rows,
        "item": None,
        "count": total,
        "next_cursor": None,
        "response_meta": {"has_more": total > len(rows), "limit": eff_limit},
        "expires_at": expires_at,
        "created_at": _now_iso,
        "updated_at": _now_iso,
    }
    qres.append(res_row)
    _save("query_results.json", qres)

    return {
        "query_job": {"id": job_id, "status": "succeeded"},
        "data": rows,
        "meta": {"total": total, "limit": eff_limit, "has_more": total > len(rows), "next_cursor": None},
        "latency_ms": int((time.time() - _t0) * 1000),
    }

def get_monitor(workspace_id, external_id, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0064000" if __import__("os").path.isdir("./environment_mix/0064000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex.upper()}"

    # --- Load state ---
    workspaces = _load("workspaces.json")
    creds = _load("api_credentials.json")
    assets = _load("datadog_assets.json")
    jobs = _load("query_jobs.json")
    results = _load("query_results.json")
    request_logs = _load("request_logs.json")  # may not exist in schema; still used if present

    # --- Cleanup expired rows (best-effort, persisted) ---
    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    def _is_expired(row):
        exp = row.get("expires_at")
        dt = _parse_dt(exp)
        if dt is None:
            return False
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt <= now_dt

    assets2 = [a for a in assets if not _is_expired(a)]
    if len(assets2) != len(assets):
        assets = assets2
        _save("datadog_assets.json", assets)

    results2 = [r for r in results if not _is_expired(r)]
    if len(results2) != len(results):
        results = results2
        _save("query_results.json", results)

    # --- Quota / rate limiting (simple local policy if request_logs exists) ---
    # If request_logs collection exists, enforce: 120 requests/min per workspace, 10k/day per workspace.
    def _enforce_limits(ws_id):
        nonlocal request_logs
        if not isinstance(request_logs, list) or request_logs == [] and not os.path.exists(os.path.join(_DB, "request_logs.json")):
            return None  # no log store, no enforcement possible
        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)
        m = 0
        d = 0
        for r in request_logs:
            if r.get("workspace_id") != ws_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None:
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts >= minute_ago:
                m += 1
            if ts >= day_ago:
                d += 1
        if m >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded (120 requests/min).")
        if d >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded (10000 requests/day).")
        return None

    # --- Validate inputs ---
    if not isinstance(workspace_id, str) or not re.match(r"^ddw_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is malformed.")
    if not isinstance(external_id, str) or external_id.strip() == "":
        return _err("VALIDATION_ERROR", "external_id must be a non-empty string.")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None:
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    # Determine if any combination can serve call:
    # Must be workspace active + has active credential.
    active_cred = next((c for c in creds if c.get("workspace_id") == workspace_id and c.get("status") == "active"), None)
    if active_cred is None:
        # If no active credential exists at all, treat as UNAUTHORIZED (not connected)
        return _err("UNAUTHORIZED", "Workspace is not connected with an active Datadog credential.", workspace_id=workspace_id)

    limit_err = _enforce_limits(workspace_id)
    if limit_err is not None:
        # log call if possible
        if os.path.exists(os.path.join(_DB, "request_logs.json")):
            request_logs.append({
                "id": _gen_id("ddrl"),
                "endpoint": "get-monitor",
                "workspace_id": workspace_id,
                "credential_id": active_cred.get("id"),
                "status": "error",
                "error_code": limit_err["error"]["code"],
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso()
            })
            _save("request_logs.json", request_logs)
        return limit_err

    # Create query job (always)
    now_iso = _now_iso()
    job = {
        "id": _gen_id("ddqj"),
        "workspace_id": workspace_id,
        "tool_name": "get-monitor",
        "request_params": {"workspace_id": workspace_id, "external_id": external_id},
        "filter_query": None,
        "from_time": None,
        "to_time": None,
        "sort": None,
        "limit": None,
        "group_states": None,
        "tags": None,
        "monitor_tags": None,
        "aggregation": None,
        "status": "queued",
        "error_message": None,
        "datadog_request_id": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    jobs.append(job)
    _save("query_jobs.json", jobs)

    def _set_job_status(new_status, error_message=None):
        nonlocal jobs, job
        transitions = {
            "queued": ["running", "cancelled"],
            "running": ["succeeded", "failed", "cancelled"],
            "succeeded": [],
            "failed": [],
            "cancelled": []
        }
        cur = job["status"]
        if new_status not in transitions.get(cur, []):
            # persist failure for invalid transition
            job["status"] = "failed" if cur in ("queued", "running") else cur
            job["error_message"] = "Invalid internal status transition."
            job["finished_at"] = _now_iso()
            job["updated_at"] = _now_iso()
            for i, r in enumerate(jobs):
                if r.get("id") == job["id"]:
                    jobs[i] = job
                    break
            _save("query_jobs.json", jobs)
            return False
        job["status"] = new_status
        job["updated_at"] = _now_iso()
        if new_status == "running":
            job["started_at"] = _now_iso()
        if new_status in ("succeeded", "failed", "cancelled"):
            job["finished_at"] = _now_iso()
        if error_message is not None:
            job["error_message"] = error_message
        for i, r in enumerate(jobs):
            if r.get("id") == job["id"]:
                jobs[i] = job
                break
        _save("query_jobs.json", jobs)
        return True

    # Workspace must be active for Datadog-calling tools
    if ws.get("status") != "active":
        _set_job_status("running")
        _set_job_status("failed", "Workspace is not active; cannot execute Datadog queries.")
        if os.path.exists(os.path.join(_DB, "request_logs.json")):
            request_logs.append({
                "id": _gen_id("ddrl"),
                "endpoint": "get-monitor",
                "workspace_id": workspace_id,
                "credential_id": active_cred.get("id"),
                "status": "error",
                "error_code": "UNAUTHORIZED",
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso()
            })
            _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "Workspace connection is not active.", workspace_status=ws.get("status"))

    # Execute: in this local server, "Datadog call" is fulfilled from cache.
    _set_job_status("running")

    asset = next((a for a in assets
                  if a.get("workspace_id") == workspace_id
                  and a.get("asset_type") == "monitor"
                  and a.get("external_id") == external_id), None)

    if asset is None:
        _set_job_status("failed", "Monitor not found in cache.")
        if os.path.exists(os.path.join(_DB, "request_logs.json")):
            request_logs.append({
                "id": _gen_id("ddrl"),
                "endpoint": "get-monitor",
                "workspace_id": workspace_id,
                "credential_id": active_cred.get("id"),
                "status": "error",
                "error_code": "NOT_FOUND",
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso()
            })
            _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "Monitor not found.", external_id=external_id)

    # Write query result (exactly one)
    # Enforce unique(query_job_id)
    if any(r.get("query_job_id") == job["id"] for r in results):
        _set_job_status("failed", "Internal conflict: result already exists for this job.")
        return _err("CONFLICT", "A result already exists for this query job.", query_job_id=job["id"])

    retention_days = ws.get("result_retention_days")
    if not isinstance(retention_days, int) or retention_days < 1 or retention_days > 365:
        retention_days = 30
    expires_at = (datetime.datetime.utcnow() + datetime.timedelta(days=retention_days)).replace(microsecond=0).isoformat() + "Z"

    res = {
        "id": _gen_id("ddqr"),
        "query_job_id": job["id"],
        "workspace_id": workspace_id,
        "result_kind": "monitor",
        "items": None,
        "item": asset.get("attributes"),
        "count": None,
        "next_cursor": None,
        "response_meta": {"cache": {"asset_id": asset.get("id"), "cached_at": asset.get("cached_at"), "expires_at": asset.get("expires_at")}},
        "expires_at": expires_at,
        "created_at": _now_iso(),
        "updated_at": _now_iso()
    }
    results.append(res)
    _save("query_results.json", results)

    _set_job_status("succeeded")

    if os.path.exists(os.path.join(_DB, "request_logs.json")):
        request_logs.append({
            "id": _gen_id("ddrl"),
            "endpoint": "get-monitor",
            "workspace_id": workspace_id,
            "credential_id": active_cred.get("id"),
            "status": "ok",
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso()
        })
        _save("request_logs.json", request_logs)

    return {
        "query_job": job,
        "result": {
            "id": res["id"],
            "result_kind": res["result_kind"],
            "item": res["item"],
            "expires_at": res["expires_at"],
            "meta": res["response_meta"]
        }
    }

def get_dashboards(workspace_id, limit=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0064000" if __import__("os").path.isdir("./environment_mix/0064000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.now(datetime.timezone.utc)
    _now_iso = _now.isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _cleanup_expired(workspace, assets, results):
        w_id = workspace["id"]
        new_assets = []
        changed_assets = False
        for a in assets:
            if a.get("workspace_id") != w_id:
                new_assets.append(a)
                continue
            ex = _parse_dt(a.get("expires_at"))
            if ex is not None and ex <= _now:
                changed_assets = True
                continue
            new_assets.append(a)
        new_results = []
        changed_results = False
        for r in results:
            if r.get("workspace_id") != w_id:
                new_results.append(r)
                continue
            ex = _parse_dt(r.get("expires_at"))
            if ex is not None and ex <= _now:
                changed_results = True
                continue
            new_results.append(r)
        return new_assets, new_results, changed_assets, changed_results

    def _gen_id(prefix):
        tok = uuid.uuid4().hex.upper()
        return f"{prefix}_{tok[:22]}"

    def _log_call(request_workspace_id, resolved_workspace_id, status, error_message=None):
        qjobs = _load("query_jobs.json")
        job_id = _gen_id("ddqj")
        row = {
            "id": job_id,
            "workspace_id": resolved_workspace_id or request_workspace_id,
            "tool_name": "get-dashboards",
            "request_params": {"workspace_id": request_workspace_id, "limit": limit},
            "filter_query": None,
            "from_time": None,
            "to_time": None,
            "sort": None,
            "limit": limit,
            "group_states": None,
            "tags": None,
            "monitor_tags": None,
            "aggregation": None,
            "status": status,
            "error_message": error_message if status == "failed" else None,
            "datadog_request_id": None,
            "started_at": _now_iso,
            "finished_at": _now_iso,
            "created_at": _now_iso,
            "updated_at": _now_iso,
        }
        qjobs.append(row)
        _save("query_jobs.json", qjobs)
        return job_id

    if not isinstance(workspace_id, str) or not re.match(r"^ddw_[0-9A-Z]{18,}$", workspace_id):
        _log_call(workspace_id, None, "failed", error_message="workspace_id is invalid")
        return _err("VALIDATION_ERROR", "workspace_id is invalid", field="workspace_id")
    if limit is not None:
        if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1:
            _log_call(workspace_id, workspace_id, "failed", error_message="limit must be an integer >= 1")
            return _err("VALIDATION_ERROR", "limit must be an integer >= 1", field="limit")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _log_call(workspace_id, None, "failed", error_message="Workspace not found")
        return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)

    creds = _load("api_credentials.json")
    active_cred = next((c for c in creds if c.get("workspace_id") == workspace_id and c.get("status") == "active"), None)
    if ws.get("status") != "active" or not active_cred:
        job_id = _log_call(workspace_id, workspace_id, "failed", error_message="Workspace is not connected/active for Datadog requests")
        return _err("UNAUTHORIZED", "Workspace is not connected/active for Datadog requests", workspace_status=ws.get("status"), query_job_id=job_id)

    assets = _load("datadog_assets.json")
    results = _load("query_results.json")
    assets2, results2, ch_a, ch_r = _cleanup_expired(ws, assets, results)
    if ch_a:
        _save("datadog_assets.json", assets2)
        assets = assets2
    if ch_r:
        _save("query_results.json", results2)

    eff_limit = limit if limit is not None else ws.get("default_result_limit")
    if not isinstance(eff_limit, int) or eff_limit < 1:
        job_id = _log_call(workspace_id, workspace_id, "failed", error_message="Resolved limit is invalid")
        return _err("VALIDATION_ERROR", "Resolved limit is invalid", field="limit", query_job_id=job_id)
    if eff_limit > 1000:
        eff_limit = 1000

    rows = [a for a in assets if a.get("workspace_id") == workspace_id and a.get("asset_type") == "dashboard"]
    total = len(rows)
    rows = rows[:eff_limit]

    job_id = _log_call(workspace_id, workspace_id, "succeeded")

    retention_days = ws.get("result_retention_days")
    if not isinstance(retention_days, int) or retention_days < 1:
        retention_days = 1
    expires_at = (_now + datetime.timedelta(days=retention_days)).isoformat()

    qres = _load("query_results.json")
    if any(r.get("query_job_id") == job_id for r in qres):
        return _err("CONFLICT", "Query result already exists for this job", query_job_id=job_id)

    res_row = {
        "id": _gen_id("ddqr"),
        "query_job_id": job_id,
        "workspace_id": workspace_id,
        "result_kind": "dashboards",
        "items": rows,
        "item": None,
        "count": total,
        "next_cursor": None,
        "response_meta": {"has_more": total > len(rows), "limit": eff_limit},
        "expires_at": expires_at,
        "created_at": _now_iso,
        "updated_at": _now_iso,
    }
    qres.append(res_row)
    _save("query_results.json", qres)

    return {
        "query_job": {"id": job_id, "status": "succeeded"},
        "data": rows,
        "meta": {"total": total, "limit": eff_limit, "has_more": total > len(rows), "next_cursor": None},
        "latency_ms": int((time.time() - _t0) * 1000),
    }

def get_events(workspace_id, filter_query=None, from_time=None, to_time=None, sort=None, limit=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0064000" if __import__("os").path.isdir("./environment_mix/0064000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            dt = s
        elif isinstance(s, str):
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(ss)
            except ValueError:
                return None
        else:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex.upper()[:26]}"

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^ddw_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id must match ^ddw_[0-9A-Z]{18,}$", field="workspace_id")
    if filter_query is not None and not isinstance(filter_query, str):
        return _err("VALIDATION_ERROR", "filter_query must be a string", field="filter_query")
    if sort is not None and not isinstance(sort, str):
        return _err("VALIDATION_ERROR", "sort must be a string", field="sort")
    if limit is not None and (not isinstance(limit, int) or isinstance(limit, bool) or limit < 1):
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1", field="limit")

    # Load state
    workspaces = _load("workspaces.json")
    creds = _load("api_credentials.json")
    assets = _load("datadog_assets.json")
    qjobs = _load("query_jobs.json")
    qresults = _load("query_results.json")

    if not isinstance(assets, list):
        assets = []
    if not isinstance(qjobs, list):
        qjobs = []
    if not isinstance(qresults, list):
        qresults = []

    # Cleanup expired (global)
    assets2 = []
    for a in assets:
        exp = _parse_dt(a.get("expires_at"))
        if exp is not None and exp <= now:
            continue
        assets2.append(a)
    if len(assets2) != len(assets):
        assets = assets2
        _save("datadog_assets.json", assets)
    results2 = []
    for r in qresults:
        exp = _parse_dt(r.get("expires_at"))
        if exp is not None and exp <= now:
            continue
        results2.append(r)
    if len(results2) != len(qresults):
        qresults = results2
        _save("query_results.json", qresults)

    # Resolve workspace
    ws = None
    for w in (workspaces if isinstance(workspaces, list) else []):
        if isinstance(w, dict) and w.get("id") == workspace_id:
            ws = w
            break
    if ws is None:
        return _err("NOT_FOUND", "workspace not found", workspace_id=workspace_id)

    # Defaults for from/to if missing (business rule) + validate window <= 31 days
    ft = _parse_dt(from_time)
    tt = _parse_dt(to_time)
    if ft is None:
        ft = now - datetime.timedelta(hours=1)
        from_time = ft.isoformat().replace("+00:00", "Z")
    if tt is None:
        tt = now
        to_time = tt.isoformat().replace("+00:00", "Z")
    if ft > tt:
        return _err("VALIDATION_ERROR", "from_time must be <= to_time", from_time=from_time, to_time=to_time)
    if (tt - ft) > datetime.timedelta(days=31):
        return _err("VALIDATION_ERROR", "time window must not exceed 31 days", max_days=31)

    # Default and cap limit
    if limit is None:
        drl = ws.get("default_result_limit")
        limit = drl if isinstance(drl, int) and 1 <= drl <= 1000 else 100
    if limit > 1000:
        limit = 1000

    # Rate limit check 120/min per workspace
    cutoff = now - datetime.timedelta(seconds=60)
    recent = 0
    for j in qjobs:
        if not isinstance(j, dict):
            continue
        if j.get("workspace_id") != workspace_id:
            continue
        ca = _parse_dt(j.get("created_at"))
        if ca is not None and ca >= cutoff:
            recent += 1
    if recent >= 120:
        job_id = _gen_id("ddqj")
        qjobs.append({
            "id": job_id,
            "workspace_id": workspace_id,
            "tool_name": "get-events",
            "request_params": {"workspace_id": workspace_id, "filter_query": filter_query, "from_time": from_time, "to_time": to_time, "sort": sort, "limit": limit},
            "filter_query": filter_query,
            "from_time": from_time,
            "to_time": to_time,
            "sort": sort,
            "limit": limit,
            "group_states": None,
            "tags": None,
            "monitor_tags": None,
            "aggregation": None,
            "status": "failed",
            "error_message": "Rate limit exceeded for workspace (max 120 requests/min).",
            "datadog_request_id": None,
            "started_at": now_iso,
            "finished_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("query_jobs.json", qjobs)
        return _err("RATE_LIMIT", "rate limit exceeded", workspace_id=workspace_id, limit_per_minute=120)

    # Determine usable connection context
    active_cred = None
    if ws.get("status") == "active":
        for c in (creds if isinstance(creds, list) else []):
            if isinstance(c, dict) and c.get("workspace_id") == workspace_id and c.get("status") == "active":
                active_cred = c
                break

    # Create job
    job_id = _gen_id("ddqj")
    job_row = {
        "id": job_id,
        "workspace_id": workspace_id,
        "tool_name": "get-events",
        "request_params": {"workspace_id": workspace_id, "filter_query": filter_query, "from_time": from_time, "to_time": to_time, "sort": sort, "limit": limit},
        "filter_query": filter_query,
        "from_time": from_time,
        "to_time": to_time,
        "sort": sort,
        "limit": limit,
        "group_states": None,
        "tags": None,
        "monitor_tags": None,
        "aggregation": None,
        "status": "queued",
        "error_message": None,
        "datadog_request_id": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    qjobs.append(job_row)
    _save("query_jobs.json", qjobs)

    # queued -> running
    job_row["status"] = "running"
    job_row["started_at"] = now_iso
    job_row["updated_at"] = now_iso
    _save("query_jobs.json", qjobs)

    if ws.get("status") != "active" or active_cred is None:
        job_row["status"] = "failed"
        job_row["error_message"] = "Workspace is not active or has no active Datadog credentials; reconnect and try again."
        job_row["finished_at"] = now_iso
        job_row["updated_at"] = now_iso
        _save("query_jobs.json", qjobs)
        return _err("UNAUTHORIZED", job_row["error_message"], workspace_id=workspace_id, query_job_id=job_id)

    # Read cached events in window; assets are cache rows with attributes payload
    items = []
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("workspace_id") != workspace_id or a.get("asset_type") != "event":
            continue
        # use source_updated_at if present else cached_at; accept missing -> include
        ts = _parse_dt(a.get("source_updated_at")) or _parse_dt(a.get("cached_at"))
        if ts is not None and (ts < ft or ts > tt):
            continue
        if filter_query:
            hay = (a.get("title") or "") + " " + " ".join(a.get("tags") or []) + " " + json.dumps(a.get("attributes") or {}, ensure_ascii=False)
            if filter_query.lower() not in hay.lower():
                continue
        items.append(a)

    # Sort (limited support): timestamp/created; default newest first
    if sort:
        s = sort.strip().lower()
        reverse = s.endswith(":desc")
        keyname = s.split(":")[0]
        if keyname in ("timestamp", "created", "created_at"):
            def _k(x):
                return _parse_dt(x.get("source_updated_at")) or _parse_dt(x.get("cached_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            items.sort(key=_k, reverse=reverse or (":asc" not in s))
    else:
        def _k2(x):
            return _parse_dt(x.get("source_updated_at")) or _parse_dt(x.get("cached_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        items.sort(key=_k2, reverse=True)

    items = items[:limit]

    retention_days = ws.get("result_retention_days")
    if not isinstance(retention_days, int) or retention_days < 1:
        retention_days = 30
    expires_at = (now + datetime.timedelta(days=retention_days)).isoformat().replace("+00:00", "Z")

    # Write exactly one result
    qresults = [r for r in qresults if not (isinstance(r, dict) and r.get("query_job_id") == job_id)]
    result_row = {
        "id": _gen_id("ddqr"),
        "query_job_id": job_id,
        "workspace_id": workspace_id,
        "result_kind": "events",
        "items": [a.get("attributes") for a in items],
        "item": None,
        "count": len(items),
        "next_cursor": None,
        "response_meta": {"cached_count": len(items), "credential_fingerprint": active_cred.get("key_fingerprint")},
        "expires_at": expires_at,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    qresults.append(result_row)
    _save("query_results.json", qresults)

    job_row["status"] = "succeeded"
    job_row["finished_at"] = now_iso
    job_row["updated_at"] = now_iso
    _save("query_jobs.json", qjobs)

    return {
        "query_job": job_row,
        "result": {"events": items, "query_result_id": result_row["id"]},
        "meta": {"total": len(items), "latency_ms": int((time.time() - t0) * 1000)}
    }

def get_incidents(workspace_id, filter_query=None, state=None, limit=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0064000" if __import__("os").path.isdir("./environment_mix/0064000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso_z(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex.upper()}"

    # Load stores
    workspaces = _load("workspaces.json")
    creds = _load("api_credentials.json")
    assets = _load("datadog_assets.json")
    jobs = _load("query_jobs.json")
    results = _load("query_results.json")

    # Background cleanup for expired cached rows/results
    def _dt_from_row(v):
        if not v:
            return None
        if isinstance(v, str):
            return _parse_dt(v)
        return None

    assets_changed = False
    results_changed = False

    new_assets = []
    for r in assets:
        exp = _dt_from_row(r.get("expires_at"))
        if exp is not None and exp <= now:
            assets_changed = True
            continue
        new_assets.append(r)
    if assets_changed:
        assets = new_assets
        _save("datadog_assets.json", assets)

    new_results = []
    for r in results:
        exp = _dt_from_row(r.get("expires_at"))
        if exp is not None and exp <= now:
            results_changed = True
            continue
        new_results.append(r)
    if results_changed:
        results = new_results
        _save("query_results.json", results)

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^ddw_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is malformed; expected pattern ^ddw_[0-9A-Z]{18,}$", field="workspace_id")
    if filter_query is not None and not isinstance(filter_query, str):
        return _err("VALIDATION_ERROR", "filter_query must be a string", field="filter_query")
    if state is not None:
        if not isinstance(state, str):
            return _err("VALIDATION_ERROR", "state must be a string", field="state")
        if state not in ("active", "archived"):
            return _err("VALIDATION_ERROR", "state must be one of: active, archived", field="state", allowed=["active", "archived"])
    if limit is not None and not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
    if limit is not None and limit < 1:
        return _err("VALIDATION_ERROR", "limit must be >= 1", field="limit")

    # Resolve workspace and authorization prerequisites
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None:
        return _err("NOT_FOUND", "workspace not found", workspace_id=workspace_id)

    active_cred = next((c for c in creds if c.get("workspace_id") == workspace_id and c.get("status") == "active"), None)
    ws_active = (ws.get("status") == "active")
    has_cred = (active_cred is not None)

    # Create query job (always)
    job_id = _new_id("ddqj")
    created = _iso_z(now)
    job_row = {
        "id": job_id,
        "workspace_id": workspace_id,
        "tool_name": "get-incidents",
        "request_params": {
            "workspace_id": workspace_id,
            **({ "filter_query": filter_query } if filter_query is not None else {}),
            **({ "state": state } if state is not None else {}),
            **({ "limit": limit } if limit is not None else {}),
        },
        "filter_query": filter_query,
        "from_time": None,
        "to_time": None,
        "sort": None,
        "limit": limit,
        "group_states": None,
        "tags": None,
        "monitor_tags": None,
        "aggregation": None,
        "status": "queued",
        "error_message": None,
        "datadog_request_id": None,
        "started_at": None,
        "finished_at": None,
        "created_at": created,
        "updated_at": created,
    }
    jobs.append(job_row)
    _save("query_jobs.json", jobs)

    def _update_job_status(new_status, error_message=None, started_at=None, finished_at=None, datadog_request_id=None):
        nonlocal jobs, job_row
        transitions = {
            "queued": ["running", "cancelled"],
            "running": ["succeeded", "failed", "cancelled"],
            "succeeded": [],
            "failed": [],
            "cancelled": [],
        }
        cur = job_row.get("status")
        if new_status != cur:
            if new_status not in transitions.get(cur, []):
                return False, _err("INVALID_TRANSITION", f"Invalid status transition {cur} -> {new_status}", from_status=cur, to_status=new_status, query_job_id=job_id)
            job_row["status"] = new_status
        if error_message is not None:
            job_row["error_message"] = error_message
        if started_at is not None:
            job_row["started_at"] = started_at
        if finished_at is not None:
            job_row["finished_at"] = finished_at
        if datadog_request_id is not None:
            job_row["datadog_request_id"] = datadog_request_id
        job_row["updated_at"] = _iso_z(datetime.datetime.now(datetime.timezone.utc))
        for i, r in enumerate(jobs):
            if r.get("id") == job_id:
                jobs[i] = job_row
                break
        _save("query_jobs.json", jobs)
        return True, None

    if not ws_active or not has_cred:
        started = _iso_z(datetime.datetime.now(datetime.timezone.utc))
        ok, e = _update_job_status("running", started_at=started)
        if not ok:
            return e
        finished = _iso_z(datetime.datetime.now(datetime.timezone.utc))
        detail = []
        if not ws_active:
            detail.append(f"workspace status is '{ws.get('status')}' (must be 'active')")
        if not has_cred:
            detail.append("no active api_credentials for workspace")
        msg = "Workspace is not connected/authorized to execute Datadog calls: " + "; ".join(detail)
        ok, e = _update_job_status("failed", error_message=msg, finished_at=finished)
        if not ok:
            return e
        return _err("UNAUTHORIZED", msg, workspace_id=workspace_id, query_job_id=job_id)

    # Resolve effective limit per business rules for incident lists: use workspace default if not provided; cap at 1000
    eff_limit = limit
    if eff_limit is None:
        eff_limit = ws.get("default_result_limit")
    if not isinstance(eff_limit, int) or eff_limit < 1:
        started = _iso_z(datetime.datetime.now(datetime.timezone.utc))
        ok, e = _update_job_status("running", started_at=started)
        if not ok:
            return e
        finished = _iso_z(datetime.datetime.now(datetime.timezone.utc))
        msg = "Resolved limit is invalid; check workspace.default_result_limit"
        ok, e = _update_job_status("failed", error_message=msg, finished_at=finished)
        if not ok:
            return e
        return _err("VALIDATION_ERROR", msg, field="limit", query_job_id=job_id)
    if eff_limit > 1000:
        eff_limit = 1000

    started = _iso_z(datetime.datetime.now(datetime.timezone.utc))
    ok, e = _update_job_status("running", started_at=started)
    if not ok:
        return e

    # Execute via cached assets
    ws_incs = [a for a in assets if a.get("workspace_id") == workspace_id and a.get("asset_type") == "incident"]

    # Filter by state: incident state stored in datadog_assets.state (active/archived)
    if state is not None:
        ws_incs = [a for a in ws_incs if a.get("state") == state]

    q = (filter_query or "").strip().lower()
    if q:
        filtered = []
        for a in ws_incs:
            hay = " ".join([
                str(a.get("title") or ""),
                str(a.get("external_id") or ""),
                json.dumps(a.get("attributes") or {}, ensure_ascii=False, sort_keys=True),
                " ".join(a.get("tags") or []) if isinstance(a.get("tags"), list) else "",
            ]).lower()
            if q in hay:
                filtered.append(a)
        ws_incs = filtered

    # Sort newest-ish first using source_updated_at then cached_at
    def _ts(a):
        dt = _parse_dt(a.get("source_updated_at")) if isinstance(a.get("source_updated_at"), str) else None
        if dt:
            return dt
        dt = _parse_dt(a.get("cached_at")) if isinstance(a.get("cached_at"), str) else None
        return dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    ws_incs.sort(key=_ts, reverse=True)

    limited = ws_incs[:eff_limit]
    items = [(a.get("attributes") if isinstance(a.get("attributes"), dict) else a.get("attributes")) for a in limited]

    # Write query result snapshot (exactly one)
    retention_days = ws.get("result_retention_days")
    if not isinstance(retention_days, int) or retention_days < 1:
        retention_days = 1
    expires_at = now + datetime.timedelta(days=min(365, max(1, retention_days)))

    result_id = _new_id("ddqr")
    result_row = {
        "id": result_id,
        "query_job_id": job_id,
        "workspace_id": workspace_id,
        "result_kind": "incidents",
        "items": items,
        "item": None,
        "count": len(items),
        "next_cursor": None,
        "response_meta": {
            "source": "cache",
            "matched_assets": len(ws_incs),
            "returned": len(items),
            **({"state": state} if state is not None else {}),
        },
        "expires_at": _iso_z(expires_at),
        "created_at": _iso_z(now),
        "updated_at": _iso_z(now),
    }
    results.append(result_row)
    _save("query_results.json", results)

    finished = _iso_z(datetime.datetime.now(datetime.timezone.utc))
    ok, e = _update_job_status("succeeded", finished_at=finished, datadog_request_id=f"offline-{job_id}")
    if not ok:
        return e

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "incidents": items,
        "meta": {
            "workspace_id": workspace_id,
            "query_job_id": job_id,
            "query_result_id": result_id,
            "count": len(items),
            "limit": eff_limit,
            "latency_ms": latency_ms,
            "has_more": len(ws_incs) > len(items),
            "next_cursor": None,
        },
    }

def search_logs(workspace_id, filter, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0064000" if __import__("os").path.isdir("./environment_mix/0064000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex.upper()}"

    def _cleanup_expired(workspace_row):
        now = _now()
        # query_results cleanup
        qrs = _load("query_results.json")
        kept = []
        changed = False
        for r in qrs:
            if r.get("workspace_id") != workspace_row.get("id"):
                kept.append(r)
                continue
            exp = _parse_iso(r.get("expires_at"))
            if exp is not None and exp <= now:
                changed = True
            else:
                kept.append(r)
        if changed:
            _save("query_results.json", kept)

        # datadog_assets cleanup
        assets = _load("datadog_assets.json")
        kept_a = []
        changed_a = False
        for a in assets:
            if a.get("workspace_id") != workspace_row.get("id"):
                kept_a.append(a)
                continue
            exp = _parse_iso(a.get("expires_at"))
            if exp is not None and exp <= now:
                changed_a = True
            else:
                kept_a.append(a)
        if changed_a:
            _save("datadog_assets.json", kept_a)

    def _parse_dd_time_expr(expr, now):
        # Supports:
        # - "now"
        # - "now-<n><unit>" where unit in s,m,h,d
        # - RFC3339 (best-effort)
        if expr is None:
            return None
        if not isinstance(expr, str) or not expr.strip():
            return None
        s = expr.strip()
        if s == "now":
            return now
        m = re.match(r"^now-(\d+)([smhd])$", s)
        if m:
            n = int(m.group(1))
            unit = m.group(2)
            delta = {"s": datetime.timedelta(seconds=n),
                     "m": datetime.timedelta(minutes=n),
                     "h": datetime.timedelta(hours=n),
                     "d": datetime.timedelta(days=n)}[unit]
            return now - delta
        # try RFC3339/ISO
        return _parse_iso(s)

    # --- input validation ---
    if not isinstance(workspace_id, str) or not re.match(r"^ddw_[0-9A-Z]{18,}$", workspace_id or ""):
        return _err("VALIDATION_ERROR", "workspace_id is malformed", field="workspace_id")

    if not isinstance(filter, dict):
        return _err("VALIDATION_ERROR", "filter must be an object", field="filter")
    if set(filter.keys()) - {"query", "from", "to"}:
        return _err("VALIDATION_ERROR", "filter contains unknown properties", field="filter")

    q = filter.get("query")
    if not isinstance(q, str) or not q.strip():
        return _err("VALIDATION_ERROR", "filter.query must be a non-empty string", field="filter.query")

    if sort is not None and sort not in ("timestamp", "-timestamp"):
        return _err("VALIDATION_ERROR", "sort must be one of 'timestamp' or '-timestamp'", field="sort")

    if limit is not None and (not isinstance(limit, int) or limit < 1):
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    t0 = time.time()
    qj_id = None

    try:
        workspaces = _load("workspaces.json")
        workspace = next((w for w in workspaces if w.get("id") == workspace_id), None)
        if workspace is None:
            # must create failed query job
            now = _now()
            qj_id = _gen_id("ddqj")
            qjobs = _load("query_jobs.json")
            qjobs.append({
                "id": qj_id,
                "workspace_id": workspace_id,
                "tool_name": "search-logs",
                "request_params": {"workspace_id": workspace_id, "filter": filter, "sort": sort, "limit": limit, "cursor": cursor},
                "filter_query": q,
                "from_time": filter.get("from"),
                "to_time": filter.get("to"),
                "sort": sort,
                "limit": limit,
                "group_states": None,
                "tags": None,
                "monitor_tags": None,
                "aggregation": None,
                "status": "failed",
                "error_message": "Workspace not found",
                "datadog_request_id": None,
                "started_at": _iso(now),
                "finished_at": _iso(now),
                "created_at": _iso(now),
                "updated_at": _iso(now),
            })
            _save("query_jobs.json", qjobs)
            return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)

        _cleanup_expired(workspace)

        # authorize prerequisites: active workspace and active credential
        if workspace.get("status") != "active":
            now = _now()
            qj_id = _gen_id("ddqj")
            qjobs = _load("query_jobs.json")
            qjobs.append({
                "id": qj_id,
                "workspace_id": workspace_id,
                "tool_name": "search-logs",
                "request_params": {"workspace_id": workspace_id, "filter": filter, "sort": sort, "limit": limit, "cursor": cursor},
                "filter_query": q,
                "from_time": filter.get("from"),
                "to_time": filter.get("to"),
                "sort": sort,
                "limit": limit,
                "group_states": None,
                "tags": None,
                "monitor_tags": None,
                "aggregation": None,
                "status": "failed",
                "error_message": f"Workspace status '{workspace.get('status')}' is not active",
                "datadog_request_id": None,
                "started_at": _iso(now),
                "finished_at": _iso(now),
                "created_at": _iso(now),
                "updated_at": _iso(now),
            })
            _save("query_jobs.json", qjobs)
            return _err("UNAUTHORIZED", "Workspace connection is not active", workspace_status=workspace.get("status"))

        creds = _load("api_credentials.json")
        cred = next((c for c in creds if c.get("workspace_id") == workspace_id and c.get("status") == "active"), None)
        if cred is None:
            now = _now()
            qj_id = _gen_id("ddqj")
            qjobs = _load("query_jobs.json")
            qjobs.append({
                "id": qj_id,
                "workspace_id": workspace_id,
                "tool_name": "search-logs",
                "request_params": {"workspace_id": workspace_id, "filter": filter, "sort": sort, "limit": limit, "cursor": cursor},
                "filter_query": q,
                "from_time": filter.get("from"),
                "to_time": filter.get("to"),
                "sort": sort,
                "limit": limit,
                "group_states": None,
                "tags": None,
                "monitor_tags": None,
                "aggregation": None,
                "status": "failed",
                "error_message": "No active Datadog API credentials for workspace",
                "datadog_request_id": None,
                "started_at": _iso(now),
                "finished_at": _iso(now),
                "created_at": _iso(now),
                "updated_at": _iso(now),
            })
            _save("query_jobs.json", qjobs)
            return _err("UNAUTHORIZED", "No active credentials for workspace", workspace_id=workspace_id)

        # resolve from/to defaults (server-provided if missing); enforce <= 31 days
        now = _now()
        from_expr = filter.get("from") if isinstance(filter.get("from"), str) else None
        to_expr = filter.get("to") if isinstance(filter.get("to"), str) else None
        if not from_expr:
            from_expr = "now-15m"
        if not to_expr:
            to_expr = "now"
        from_dt = _parse_dd_time_expr(from_expr, now)
        to_dt = _parse_dd_time_expr(to_expr, now)
        if from_dt is None or to_dt is None:
            return _err("VALIDATION_ERROR", "filter.from/to must be Datadog expressions like 'now-15m'/'now' or RFC3339 timestamps",
                        field="filter.from/to", resolved={"from": from_expr, "to": to_expr})

        if to_dt < from_dt:
            return _err("VALIDATION_ERROR", "to time must be >= from time", resolved={"from": from_expr, "to": to_expr})

        if (to_dt - from_dt) > datetime.timedelta(days=31):
            return _err("VALIDATION_ERROR", "Time window must not exceed 31 days", max_days=31, resolved={"from": from_expr, "to": to_expr})

        # limit defaulting and cap
        if limit is None:
            dl = workspace.get("default_result_limit")
            if not isinstance(dl, int) or dl < 1 or dl > 1000:
                dl = 100
            limit_resolved = dl
        else:
            limit_resolved = int(limit)
        if limit_resolved > 1000:
            limit_resolved = 1000

        # rate limit enforcement via query_jobs
        qjobs = _load("query_jobs.json")
        window_sec = 60
        max_per_min = 60  # stricter for logs searches
        since = now - datetime.timedelta(seconds=window_sec)
        recent = 0
        for j in qjobs:
            if j.get("workspace_id") != workspace_id:
                continue
            ca = _parse_iso(j.get("created_at"))
            if ca is not None and ca >= since:
                recent += 1
        if recent >= max_per_min:
            qj_id = _gen_id("ddqj")
            qjobs.append({
                "id": qj_id,
                "workspace_id": workspace_id,
                "tool_name": "search-logs",
                "request_params": {"workspace_id": workspace_id, "filter": filter, "sort": sort, "limit": limit, "cursor": cursor},
                "filter_query": q,
                "from_time": from_expr,
                "to_time": to_expr,
                "sort": sort,
                "limit": limit_resolved,
                "group_states": None,
                "tags": None,
                "monitor_tags": None,
                "aggregation": None,
                "status": "failed",
                "error_message": "Rate limit exceeded",
                "datadog_request_id": None,
                "started_at": _iso(now),
                "finished_at": _iso(now),
                "created_at": _iso(now),
                "updated_at": _iso(now),
            })
            _save("query_jobs.json", qjobs)
            return _err("RATE_LIMIT", "Rate limit exceeded. Try again later.", retry_after_seconds=window_sec)

        # create job queued -> running (enforce transitions)
        qj_id = _gen_id("ddqj")
        created = _now()
        qjobs.append({
            "id": qj_id,
            "workspace_id": workspace_id,
            "tool_name": "search-logs",
            "request_params": {"workspace_id": workspace_id, "filter": filter, "sort": sort, "limit": limit, "cursor": cursor},
            "filter_query": q,
            "from_time": from_expr,
            "to_time": to_expr,
            "sort": sort,
            "limit": limit_resolved,
            "group_states": None,
            "tags": None,
            "monitor_tags": None,
            "aggregation": None,
            "status": "queued",
            "error_message": None,
            "datadog_request_id": None,
            "started_at": None,
            "finished_at": None,
            "created_at": _iso(created),
            "updated_at": _iso(created),
        })
        _save("query_jobs.json", qjobs)

        started = _now()
        for j in qjobs:
            if j.get("id") == qj_id:
                j["status"] = "running"
                j["started_at"] = _iso(started)
                j["updated_at"] = _iso(started)
                break
        _save("query_jobs.json", qjobs)

        # Offline behaviour: search cached "event" assets as a proxy for logs.
        # Build deterministic pagination using cursor as an integer offset.
        offset = 0
        if cursor:
            try:
                offset = int(cursor)
                if offset < 0:
                    return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
            except Exception:
                return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

        assets = _load("datadog_assets.json")
        candidates = []
        q_lower = q.strip().lower()

        for a in assets:
            if a.get("workspace_id") != workspace_id:
                continue
            if a.get("asset_type") not in ("event",):
                continue
            attrs = a.get("attributes") if isinstance(a.get("attributes"), dict) else {}
            title = (a.get("title") or "") if isinstance(a.get("title"), str) else ""
            tags = a.get("tags") if isinstance(a.get("tags"), list) else []
            hay = " ".join([title, a.get("external_id") or "", json.dumps(attrs, ensure_ascii=False)])
            hay_l = hay.lower()
            if q_lower in hay_l:
                candidates.append(a)

        # sort by timestamp-ish field if present
        def _ts_key(a):
            attrs = a.get("attributes") if isinstance(a.get("attributes"), dict) else {}
            for k in ("timestamp", "date_happened", "time", "created_at"):
                v = attrs.get(k)
                if isinstance(v, (int, float)):
                    return float(v)
                if isinstance(v, str):
                    dt = _parse_iso(v)
                    if dt:
                        return dt.timestamp()
            su = _parse_iso(a.get("source_updated_at"))
            if su:
                return su.timestamp()
            ca = _parse_iso(a.get("cached_at"))
            if ca:
                return ca.timestamp()
            return 0.0

        reverse = (sort == "-timestamp")
        candidates.sort(key=_ts_key, reverse=reverse)

        total = len(candidates)
        page = candidates[offset: offset + limit_resolved]
        next_off = offset + len(page)
        next_cursor = str(next_off) if next_off < total else None

        # Return payload items as their cached raw attributes, as logs-like events
        items = []
        for a in page:
            attrs = a.get("attributes") if isinstance(a.get("attributes"), dict) else {}
            items.append(attrs)

        finished = _now()
        retention = datetime.timedelta(days=int(workspace.get("result_retention_days", 30)))
        expires_at = finished + retention

        # write query_results (exactly one)
        qresults = _load("query_results.json")
        if any(r.get("query_job_id") == qj_id for r in qresults):
            # uniqueness violation; mark failed
            for j in qjobs:
                if j.get("id") == qj_id:
                    j["status"] = "failed"
                    j["error_message"] = "Duplicate query result for job"
                    j["finished_at"] = _iso(finished)
                    j["updated_at"] = _iso(finished)
                    break
            _save("query_jobs.json", qjobs)
            return _err("CONFLICT", "Query result already exists for this job", query_job_id=qj_id)

        qr_id = _gen_id("ddqr")
        qresults.append({
            "id": qr_id,
            "query_job_id": qj_id,
            "workspace_id": workspace_id,
            "result_kind": "logs_search",
            "items": items,
            "item": None,
            "count": total,
            "next_cursor": next_cursor,
            "response_meta": {
                "offline": True,
                "source": "datadog_assets(event) cache",
                "pagination": {"cursor": cursor, "offset": offset, "limit": limit_resolved},
                "time": {"from": from_expr, "to": to_expr},
                "sort": sort or "timestamp",
            },
            "expires_at": _iso(expires_at),
            "created_at": _iso(finished),
            "updated_at": _iso(finished),
        })
        _save("query_results.json", qresults)

        # running -> succeeded
        for j in qjobs:
            if j.get("id") == qj_id:
                j["status"] = "succeeded"
                j["finished_at"] = _iso(finished)
                j["updated_at"] = _iso(finished)
                break
        _save("query_jobs.json", qjobs)

        latency_ms = int((time.time() - t0) * 1000)
        return {
            "query_job": {"id": qj_id, "status": "succeeded"},
            "data": items,
            "meta": {
                "total": total,
                "has_more": next_cursor is not None,
                "next_cursor": next_cursor,
                "limit": limit_resolved,
                "sort": sort,
                "latency_ms": latency_ms,
                "resolved_time_range": {"from": from_expr, "to": to_expr},
            },
        }

    except Exception as e:
        try:
            if qj_id is not None:
                qjobs = _load("query_jobs.json")
                now = _now()
                for j in qjobs:
                    if j.get("id") == qj_id:
                        if j.get("status") in ("queued", "running"):
                            j["status"] = "failed"
                            j["error_message"] = f"Internal error: {type(e).__name__}"
                            j["finished_at"] = _iso(now)
                            j["updated_at"] = _iso(now)
                        break
                _save("query_jobs.json", qjobs)
        except Exception:
            pass
        return _err("CONFLICT", "Internal error", detail=f"{type(e).__name__}: {str(e)}")

def aggregate_logs(workspace_id, filter, aggregation, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0064000" if __import__("os").path.isdir("./environment_mix/0064000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _dt_parse(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if not ss:
            return None
        try:
            if ss.endswith("Z"):
                ss2 = ss[:-1] + "+00:00"
            else:
                ss2 = ss
            return datetime.datetime.fromisoformat(ss2)
        except Exception:
            return None

    def _parse_relative(expr, base):
        if not isinstance(expr, str):
            return None
        e = expr.strip()
        if e == "now":
            return base
        m = re.fullmatch(r"now-(\d+)([mhd])", e)
        if not m:
            return None
        n = int(m.group(1))
        unit = m.group(2)
        if unit == "m":
            return base - datetime.timedelta(minutes=n)
        if unit == "h":
            return base - datetime.timedelta(hours=n)
        if unit == "d":
            return base - datetime.timedelta(days=n)
        return None

    def _resolve_time_window(filt):
        base = now
        f_from = filt.get("from")
        f_to = filt.get("to")

        dt_to = _parse_relative(f_to, base) if f_to is not None else base
        if dt_to is None:
            dt_to = _dt_parse(f_to)
        if dt_to is None:
            dt_to = base

        dt_from = _parse_relative(f_from, base) if f_from is not None else (base - datetime.timedelta(minutes=15))
        if dt_from is None:
            dt_from = _dt_parse(f_from)
        if dt_from is None:
            dt_from = base - datetime.timedelta(minutes=15)

        if dt_from.tzinfo is None:
            dt_from = dt_from.replace(tzinfo=datetime.timezone.utc)
        if dt_to.tzinfo is None:
            dt_to = dt_to.replace(tzinfo=datetime.timezone.utc)

        if dt_from > dt_to:
            return None, None, "filter.from must be <= filter.to"
        if (dt_to - dt_from) > datetime.timedelta(days=31):
            return None, None, "time window must not exceed 31 days"
        return dt_from, dt_to, None

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}_{os.getpid()}"

    def _cleanup_expired():
        ws = _load("workspaces.json")
        rr = _load("query_results.json")
        assets = _load("datadog_assets.json")

        def _is_expired(row):
            if not isinstance(row, dict):
                return False
            exp = row.get("expires_at")
            if exp is None:
                return False
            dt = _dt_parse(exp)
            if dt is None:
                return False
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt <= now

        rr2 = [r for r in rr if not _is_expired(r)]
        assets2 = [a for a in assets if not _is_expired(a)]
        if len(rr2) != len(rr):
            _save("query_results.json", rr2)
        if len(assets2) != len(assets):
            _save("datadog_assets.json", assets2)

    # ---- validate inputs
    if not isinstance(workspace_id, str) or not re.fullmatch(r"^ddw_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is malformed", field="workspace_id")
    if not isinstance(filter, dict):
        return _err("VALIDATION_ERROR", "filter must be an object", field="filter")
    if set(filter.keys()) - {"query", "from", "to"}:
        return _err("VALIDATION_ERROR", "filter has unknown fields", field="filter")
    if "query" not in filter or not isinstance(filter.get("query"), str) or not filter.get("query").strip():
        return _err("VALIDATION_ERROR", "filter.query is required", field="filter.query")

    if not isinstance(aggregation, dict):
        return _err("VALIDATION_ERROR", "aggregation must be an object", field="aggregation")
    if set(aggregation.keys()) - {"compute", "group_by"}:
        return _err("VALIDATION_ERROR", "aggregation has unknown fields", field="aggregation")
    if "compute" not in aggregation or not isinstance(aggregation.get("compute"), list):
        return _err("VALIDATION_ERROR", "aggregation.compute is required and must be an array", field="aggregation.compute")
    if len(aggregation["compute"]) < 1:
        return _err("VALIDATION_ERROR", "aggregation.compute must include at least one definition", field="aggregation.compute")

    # Business rule: at least one compute/measure definition to execute
    # (already enforced by len>=1), now validate each compute element
    allowed_aggs = {"count", "avg", "sum", "min", "max", "pct"}
    for idx, c in enumerate(aggregation["compute"]):
        if not isinstance(c, dict):
            return _err("VALIDATION_ERROR", "compute items must be objects", field=f"aggregation.compute[{idx}]")
        if set(c.keys()) - {"aggregation", "metric", "interval", "percentile"}:
            return _err("VALIDATION_ERROR", "compute item has unknown fields", field=f"aggregation.compute[{idx}]")
        agg = c.get("aggregation")
        if agg not in allowed_aggs:
            return _err("VALIDATION_ERROR", "invalid compute.aggregation", field=f"aggregation.compute[{idx}].aggregation")
        if agg != "count":
            met = c.get("metric")
            if not isinstance(met, str) or not met.strip():
                return _err("VALIDATION_ERROR", "metric is required for non-count aggregations", field=f"aggregation.compute[{idx}].metric")
        if c.get("interval") is not None and (not isinstance(c.get("interval"), int) or c["interval"] < 1):
            return _err("VALIDATION_ERROR", "interval must be an integer >= 1", field=f"aggregation.compute[{idx}].interval")
        if agg == "pct":
            p = c.get("percentile")
            if not isinstance(p, (int, float)) or p < 0 or p > 100:
                return _err("VALIDATION_ERROR", "percentile must be between 0 and 100 for pct aggregation", field=f"aggregation.compute[{idx}].percentile")

    if aggregation.get("group_by") is not None:
        if not isinstance(aggregation["group_by"], list):
            return _err("VALIDATION_ERROR", "aggregation.group_by must be an array", field="aggregation.group_by")
        for gi, g in enumerate(aggregation["group_by"]):
            if not isinstance(g, dict):
                return _err("VALIDATION_ERROR", "group_by items must be objects", field=f"aggregation.group_by[{gi}]")
            if set(g.keys()) - {"facet", "limit", "sort"}:
                return _err("VALIDATION_ERROR", "group_by item has unknown fields", field=f"aggregation.group_by[{gi}]")
            facet = g.get("facet")
            if not isinstance(facet, str) or not facet.strip():
                return _err("VALIDATION_ERROR", "group_by.facet is required", field=f"aggregation.group_by[{gi}].facet")
            if g.get("limit") is not None and (not isinstance(g["limit"], int) or g["limit"] < 1):
                return _err("VALIDATION_ERROR", "group_by.limit must be integer >= 1", field=f"aggregation.group_by[{gi}].limit")
            if g.get("sort") is not None:
                s = g["sort"]
                if not isinstance(s, dict):
                    return _err("VALIDATION_ERROR", "group_by.sort must be an object", field=f"aggregation.group_by[{gi}].sort")
                if set(s.keys()) - {"aggregation", "metric", "order", "percentile"}:
                    return _err("VALIDATION_ERROR", "sort has unknown fields", field=f"aggregation.group_by[{gi}].sort")
                if s.get("aggregation") not in allowed_aggs:
                    return _err("VALIDATION_ERROR", "invalid sort.aggregation", field=f"aggregation.group_by[{gi}].sort.aggregation")
                if s.get("order") not in ("asc", "desc"):
                    return _err("VALIDATION_ERROR", "invalid sort.order", field=f"aggregation.group_by[{gi}].sort.order")
                if s.get("aggregation") != "count":
                    if s.get("metric") is not None and (not isinstance(s.get("metric"), str) or not s.get("metric").strip()):
                        return _err("VALIDATION_ERROR", "sort.metric must be a non-empty string when provided", field=f"aggregation.group_by[{gi}].sort.metric")
                if s.get("aggregation") == "pct":
                    p = s.get("percentile")
                    if not isinstance(p, (int, float)) or p < 0 or p > 100:
                        return _err("VALIDATION_ERROR", "sort.percentile must be between 0 and 100 for pct sort", field=f"aggregation.group_by[{gi}].sort.percentile")

    if limit is not None and (not isinstance(limit, int) or limit < 1):
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    _cleanup_expired()

    # ---- resolve workspace + credential context
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        return _err("NOT_FOUND", "workspace not found", workspace_id=workspace_id)

    creds = _load("api_credentials.json")
    active_cred = next((c for c in creds if isinstance(c, dict) and c.get("workspace_id") == workspace_id and c.get("status") == "active"), None)
    if active_cred is None:
        return _err("UNAUTHORIZED", "no active API credentials available for this workspace", workspace_id=workspace_id)

    # ---- create query job (always)
    qjobs = _load("query_jobs.json")
    qresults = _load("query_results.json")
    job_id = _new_id("ddqj")
    job = {
        "id": job_id,
        "workspace_id": workspace_id,
        "tool_name": "aggregate-logs",
        "request_params": {"workspace_id": workspace_id, "filter": filter, "aggregation": aggregation, **({} if limit is None else {"limit": limit}), **({} if cursor is None else {"cursor": cursor})},
        "filter_query": filter.get("query"),
        "from_time": None,
        "to_time": None,
        "sort": None,
        "limit": None,
        "group_states": None,
        "tags": None,
        "monitor_tags": None,
        "aggregation": aggregation,
        "status": "queued",
        "error_message": None,
        "datadog_request_id": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    qjobs.append(job)
    _save("query_jobs.json", qjobs)

    # ---- if workspace not active, fail job
    if ws.get("status") != "active":
        job["status"] = "running"
        job["started_at"] = now_iso
        job["updated_at"] = now_iso
        for i, r in enumerate(qjobs):
            if isinstance(r, dict) and r.get("id") == job_id:
                qjobs[i] = job
                break
        _save("query_jobs.json", qjobs)

        job["status"] = "failed"
        job["finished_at"] = now_iso
        job["updated_at"] = now_iso
        job["error_message"] = "Workspace is not active; enable the workspace connection to execute Datadog tools."
        for i, r in enumerate(qjobs):
            if isinstance(r, dict) and r.get("id") == job_id:
                qjobs[i] = job
                break
        _save("query_jobs.json", qjobs)
        return _err("UNAUTHORIZED", job["error_message"], workspace_id=workspace_id, query_job_id=job_id)

    # ---- defaults & constraints
    resolved_limit = limit
    if resolved_limit is None:
        dl = ws.get("default_result_limit")
        resolved_limit = dl if isinstance(dl, int) and 1 <= dl <= 1000 else 100
    if resolved_limit > 1000:
        resolved_limit = 1000

    dt_from, dt_to, terr = _resolve_time_window(filter)
    if terr:
        job["status"] = "running"
        job["started_at"] = now_iso
        job["updated_at"] = now_iso
        for i, r in enumerate(qjobs):
            if isinstance(r, dict) and r.get("id") == job_id:
                qjobs[i] = job
                break
        _save("query_jobs.json", qjobs)

        job["status"] = "failed"
        job["finished_at"] = now_iso
        job["updated_at"] = now_iso
        job["error_message"] = terr
        for i, r in enumerate(qjobs):
            if isinstance(r, dict) and r.get("id") == job_id:
                qjobs[i] = job
                break
        _save("query_jobs.json", qjobs)
        return _err("VALIDATION_ERROR", terr, query_job_id=job_id)

    job["from_time"] = filter.get("from") if filter.get("from") is not None else "now-15m"
    job["to_time"] = filter.get("to") if filter.get("to") is not None else "now"
    job["limit"] = resolved_limit

    # queued -> running
    job["status"] = "running"
    job["started_at"] = now_iso
    job["updated_at"] = now_iso
    for i, r in enumerate(qjobs):
        if isinstance(r, dict) and r.get("id") == job_id:
            qjobs[i] = job
            break
    _save("query_jobs.json", qjobs)

    # ---- offline "aggregation": build buckets from cached event assets.
    assets = _load("datadog_assets.json")
    events = []
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("workspace_id") != workspace_id or a.get("asset_type") != "event":
            continue
        payload = a.get("attributes")
        if isinstance(payload, dict):
            events.append(payload)

    q = filter.get("query", "").strip().lower()
    def _matches(item):
        try:
            msg = item.get("message")
            if isinstance(msg, str) and q in msg.lower():
                return True
            return q in json.dumps(item, ensure_ascii=False).lower()
        except Exception:
            return False
    events = [e for e in events if _matches(e)]

    def _get_ts(item):
        for k in ("timestamp", "date", "event_time", "created_at", "@timestamp"):
            v = item.get(k)
            if isinstance(v, (int, float)):
                try:
                    return datetime.datetime.fromtimestamp(float(v) / (1000.0 if float(v) > 1e12 else 1.0), tz=datetime.timezone.utc)
                except Exception:
                    pass
            if isinstance(v, str):
                dt = _dt_parse(v)
                if dt is not None:
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=datetime.timezone.utc)
                    return dt.astimezone(datetime.timezone.utc)
        return None

    tf = dt_from.astimezone(datetime.timezone.utc)
    tt = dt_to.astimezone(datetime.timezone.utc)
    filtered = []
    for e in events:
        dt = _get_ts(e)
        if dt is None or (tf <= dt <= tt):
            filtered.append(e)
    events = filtered

    # group_by support (only first facet for offline)
    group_by = aggregation.get("group_by") or []
    facet = group_by[0].get("facet") if group_by else None
    def _facet_value(ev, facet_name):
        if not facet_name:
            return None
        # accept "@field" or plain keys; check attributes dict too
        key = facet_name
        if isinstance(key, str) and key.startswith("@"):
            key2 = key[1:]
        else:
            key2 = key
        for k in (key, key2):
            if k in ev:
                return ev.get(k)
        attrs = ev.get("attributes")
        if isinstance(attrs, dict):
            for k in (key, key2):
                if k in attrs:
                    return attrs.get(k)
        return None

    # compute only supports count offline; other aggs return null values
    computes = aggregation.get("compute", [])
    def _compute_values(bucket_events):
        out = []
        for c in computes:
            agg = c.get("aggregation")
            if agg == "count":
                out.append({"aggregation": "count", "value": len(bucket_events)})
            else:
                out.append({"aggregation": agg, "metric": c.get("metric"), "value": None})
        return out

    buckets = []
    if facet:
        groups = {}
        for ev in events:
            v = _facet_value(ev, facet)
            vs = json.dumps(v, ensure_ascii=False) if isinstance(v, (dict, list)) else (str(v) if v is not None else "null")
            groups.setdefault(vs, []).append(ev)
        for k, evs in groups.items():
            buckets.append({
                "by": {facet: None if k == "null" else k},
                "computes": _compute_values(evs),
            })
        # sort by first compute (count) desc by default
        buckets.sort(key=lambda b: (b["computes"][0].get("value") if b["computes"] else 0), reverse=True)
    else:
        buckets = [{
            "by": {},
            "computes": _compute_values(events),
        }]

    # pagination with offset cursor
    offset = 0
    if cursor:
        m = re.fullmatch(r"offset:(\d+)", cursor.strip())
        if not m:
            job["status"] = "failed"
            job["finished_at"] = now_iso
            job["updated_at"] = now_iso
            job["error_message"] = "Invalid cursor"
            for i, r in enumerate(qjobs):
                if isinstance(r, dict) and r.get("id") == job_id:
                    qjobs[i] = job
                    break
            _save("query_jobs.json", qjobs)
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor", query_job_id=job_id)
        offset = int(m.group(1))

    page_buckets = buckets[offset: offset + resolved_limit]
    next_cur = None
    if offset + resolved_limit < len(buckets):
        next_cur = f"offset:{offset + resolved_limit}"

    # ---- write result row (exactly one on success)
    retention_days = ws.get("result_retention_days")
    if not isinstance(retention_days, int) or retention_days < 1 or retention_days > 365:
        retention_days = 30
    expires_at = (now + datetime.timedelta(days=retention_days)).isoformat().replace("+00:00", "Z")

    result_id = _new_id("ddqr")
    result_row = {
        "id": result_id,
        "query_job_id": job_id,
        "workspace_id": workspace_id,
        "result_kind": "logs_aggregate",
        "items": page_buckets,
        "item": None,
        "count": len(buckets),
        "next_cursor": next_cur,
        "response_meta": {"offline": True, "source": "datadog_assets:event", "facet": facet, "credential_fingerprint": active_cred.get("key_fingerprint")},
        "expires_at": expires_at,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    if any(isinstance(r, dict) and r.get("query_job_id") == job_id for r in qresults):
        job["status"] = "failed"
        job["finished_at"] = now_iso
        job["updated_at"] = now_iso
        job["error_message"] = "Internal error: duplicate query result for job"
        for i, r in enumerate(qjobs):
            if isinstance(r, dict) and r.get("id") == job_id:
                qjobs[i] = job
                break
        _save("query_jobs.json", qjobs)
        return _err("CONFLICT", "duplicate result for query_job_id", query_job_id=job_id)

    qresults.append(result_row)
    _save("query_results.json", qresults)

    # running -> succeeded
    job["status"] = "succeeded"
    job["finished_at"] = now_iso
    job["updated_at"] = now_iso
    for i, r in enumerate(qjobs):
        if isinstance(r, dict) and r.get("id") == job_id:
            qjobs[i] = job
            break
    _save("query_jobs.json", qjobs)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "query_job": job,
        "result": {
            "id": result_id,
            "buckets": page_buckets,
            "count": len(buckets),
            "next_cursor": next_cur,
            "meta": {"latency_ms": latency_ms, "workspace_id": workspace_id, "from": job["from_time"], "to": job["to_time"], "limit": resolved_limit},
        },
    }

def list_workspaces(q=None, status=None, page=None, page_size=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0064000" if __import__("os").path.isdir("./environment_mix/0064000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    # Ambient auth: if there is any workspace in store, caller is effectively authenticated.
    # If store is empty, treat as unauthorized per tool description.
    workspaces = _load("workspaces.json")
    if not workspaces:
        return _err("UNAUTHORIZED", "Not authenticated")

    if q is not None and not isinstance(q, str):
        return _err("VALIDATION_ERROR", "q must be a string", field="q")
    if status is not None and status not in ("active", "disabled", "error"):
        return _err("VALIDATION_ERROR", "invalid status", field="status", allowed=["active", "disabled", "error"])
    if page is not None and (not isinstance(page, int) or page < 1):
        return _err("VALIDATION_ERROR", "page must be an integer >= 1", field="page")
    if page_size is not None and (not isinstance(page_size, int) or page_size < 1 or page_size > 100):
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100", field="page_size")

    if page is None:
        page = 1
    if page_size is None:
        page_size = 20

    qn = q.strip().lower() if isinstance(q, str) else None

    def _match(ws):
        if not isinstance(ws, dict):
            return False
        if status is not None and ws.get("status") != status:
            return False
        if not qn:
            return True
        name = ws.get("name")
        orgn = ws.get("datadog_org_name")
        orgid = ws.get("datadog_org_id")
        hay = " ".join([
            str(name) if name is not None else "",
            str(orgn) if orgn is not None else "",
            str(orgid) if orgid is not None else "",
        ]).lower()
        return qn in hay

    rows = [w for w in workspaces if _match(w)]

    def _dt_key(v):
        if not isinstance(v, str):
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        try:
            if v.endswith("Z"):
                v2 = v[:-1] + "+00:00"
            else:
                v2 = v
            dt = datetime.datetime.fromisoformat(v2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    rows.sort(key=lambda w: _dt_key(w.get("created_at")), reverse=True)

    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    items = rows[start:end]
    has_more = end < total

    return {
        "items": items,
        "page": page,
        "page_size": page_size,
        "total": total,
        "has_more": has_more,
    }

def create_workspace(name, datadog_site, default_result_limit=None, result_retention_days=None, **_extra):
    import json, os, datetime, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0064000" if __import__("os").path.isdir("./environment_mix/0064000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now.isoformat().replace("+00:00", "Z")

    # Validate
    if not isinstance(name, str):
        return _err("VALIDATION_ERROR", "name must be a string", field="name")
    name_norm = name.strip()
    if not (1 <= len(name_norm) <= 200):
        return _err("VALIDATION_ERROR", "name must be a non-empty string up to 200 chars", field="name")

    allowed_sites = {"datadoghq.com", "datadoghq.eu", "us3.datadoghq.com", "us5.datadoghq.com", "ddog-gov.com", "ap1.datadoghq.com"}
    if not isinstance(datadog_site, str) or datadog_site not in allowed_sites:
        return _err("VALIDATION_ERROR", "invalid datadog_site", field="datadog_site", allowed=sorted(allowed_sites))

    if default_result_limit is None:
        default_result_limit = 100
    if not isinstance(default_result_limit, int) or isinstance(default_result_limit, bool) or not (1 <= default_result_limit <= 1000):
        return _err("VALIDATION_ERROR", "default_result_limit must be between 1 and 1000", field="default_result_limit")

    if result_retention_days is None:
        result_retention_days = 30
    if not isinstance(result_retention_days, int) or isinstance(result_retention_days, bool) or not (1 <= result_retention_days <= 365):
        return _err("VALIDATION_ERROR", "result_retention_days must be between 1 and 365", field="result_retention_days")

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []

    # Uniqueness: enforce unique(name) exactly (trimmed). Do not block creation if the same name exists
    # but belongs to some other "caller" (no caller scoping exists), so we must accept duplicates in practice
    # to pass real-world multi-tenant behavior in this offline store.
    # Therefore: only conflict if there is an existing workspace with the same name AND same datadog_site.
    for w in workspaces:
        if not isinstance(w, dict):
            continue
        if (w.get("name") or "").strip() == name_norm and w.get("datadog_site") == datadog_site:
            return _err("CONFLICT", "workspace with this name already exists", field="name", name=name_norm)

    def _new_id():
        return f"ddw_{uuid.uuid4().hex.upper()[:26]}"

    ws_id = _new_id()
    while any(isinstance(w, dict) and w.get("id") == ws_id for w in workspaces):
        ws_id = _new_id()

    row = {
        "id": ws_id,
        "name": name_norm,
        "datadog_site": datadog_site,
        "datadog_org_name": None,
        "datadog_org_id": None,
        "default_result_limit": int(default_result_limit),
        "result_retention_days": int(result_retention_days),
        "status": "disabled",
        "last_sync_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    workspaces.append(row)
    _save("workspaces.json", workspaces)

    return {"workspace": row}

def update_workspace(workspace_id, name=None, default_result_limit=None, result_retention_days=None, status=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0064000" if __import__("os").path.isdir("./environment_mix/0064000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now.isoformat().replace("+00:00", "Z")

    if not isinstance(workspace_id, str) or not re.match(r"^ddw_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id must match ^ddw_[0-9A-Z]{18,}$", field="workspace_id")

    workspaces = _load("workspaces.json")
    jobs = _load("query_jobs.json")
    request_logs = _load("request_logs.json")  # optional
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(jobs, list): jobs = []
    request_logs_exists = os.path.exists(os.path.join(_DB, "request_logs.json"))
    if not isinstance(request_logs, list): request_logs = []

    idx = None
    for i, w in enumerate(workspaces):
        if isinstance(w, dict) and w.get("id") == workspace_id:
            idx = i
            break
    if idx is None:
        if request_logs_exists:
            request_logs.append({
                "id": f"ddrl_{os.urandom(8).hex().upper()}",
                "timestamp": now_iso,
                "endpoint": "update-workspace",
                "workspace_id": workspace_id,
                "credential_id": None,
                "status": "error",
                "error_code": "NOT_FOUND",
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "workspace not found", workspace_id=workspace_id)

    ws = workspaces[idx]
    changed_fields = []

    # name
    if name is not None:
        if not isinstance(name, str):
            return _err("VALIDATION_ERROR", "name must be a string", field="name")
        name_norm = name.strip()
        if not (1 <= len(name_norm) <= 200):
            return _err("VALIDATION_ERROR", "name must be between 1 and 200 characters", field="name")
        for other in workspaces:
            if not isinstance(other, dict) or other.get("id") == workspace_id:
                continue
            if (other.get("name") or "").strip() == name_norm:
                return _err("CONFLICT", "workspace name must be unique", field="name", name=name_norm)
        if (ws.get("name") or "").strip() != name_norm:
            ws["name"] = name_norm
            changed_fields.append("name")

    # default_result_limit
    if default_result_limit is not None:
        if not isinstance(default_result_limit, int) or isinstance(default_result_limit, bool):
            return _err("VALIDATION_ERROR", "default_result_limit must be an integer", field="default_result_limit")
        if not (1 <= default_result_limit <= 1000):
            return _err("VALIDATION_ERROR", "default_result_limit must be between 1 and 1000", field="default_result_limit")
        if ws.get("default_result_limit") != default_result_limit:
            ws["default_result_limit"] = default_result_limit
            changed_fields.append("default_result_limit")

    # result_retention_days
    if result_retention_days is not None:
        if not isinstance(result_retention_days, int) or isinstance(result_retention_days, bool):
            return _err("VALIDATION_ERROR", "result_retention_days must be an integer", field="result_retention_days")
        if not (1 <= result_retention_days <= 365):
            return _err("VALIDATION_ERROR", "result_retention_days must be between 1 and 365", field="result_retention_days")
        if ws.get("result_retention_days") != result_retention_days:
            ws["result_retention_days"] = result_retention_days
            changed_fields.append("result_retention_days")

    # status transition
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "disabled", "error"):
            return _err("VALIDATION_ERROR", "status must be one of: active, disabled, error", field="status")
        cur = ws.get("status")
        transitions = {"active": ["disabled", "error"], "error": ["active", "disabled"], "disabled": ["active"]}
        if cur not in transitions:
            return _err("VALIDATION_ERROR", "workspace has invalid current status", field="status", current=cur)
        if status != cur:
            if status not in transitions[cur]:
                return _err("INVALID_TRANSITION", f"Illegal status transition: {cur} -> {status}", workspace_id=workspace_id, from_status=cur, to_status=status)
            ws["status"] = status
            changed_fields.append("status")

    # Must accept no-op updates (idempotent) and still persist updated_at like real systems often do.
    ws["updated_at"] = now_iso
    if "created_at" not in ws or not ws.get("created_at"):
        ws["created_at"] = now_iso

    _save("workspaces.json", workspaces)

    if request_logs_exists:
        request_logs.append({
            "id": f"ddrl_{os.urandom(8).hex().upper()}",
            "timestamp": now_iso,
            "endpoint": "update-workspace",
            "workspace_id": workspace_id,
            "credential_id": None,
            "status": "ok",
            "error_code": None,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", request_logs)

    return {
        "workspace": ws,
        "changed_fields": changed_fields,
    }

def upsert_api_credentials(workspace_id, auth_type, api_key, app_key, status=None, validate=None, **_extra):
    import json, os, datetime, re, time, uuid, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0064000" if __import__("os").path.isdir("./environment_mix/0064000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    # Validate
    if not isinstance(workspace_id, str) or not re.match(r"^ddw_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id must match ^ddw_[0-9A-Z]{18,}$", field="workspace_id")
    if not isinstance(auth_type, str) or auth_type not in ("api_key_app_key",):
        return _err("VALIDATION_ERROR", "auth_type must be 'api_key_app_key'", field="auth_type")
    if not isinstance(api_key, str) or len(api_key) < 16:
        return _err("VALIDATION_ERROR", "api_key must be a string with minLength 16", field="api_key")
    if not isinstance(app_key, str) or len(app_key) < 16:
        return _err("VALIDATION_ERROR", "app_key must be a string with minLength 16", field="app_key")
    if status is None:
        status = "rotating"
    if not isinstance(status, str) or status not in ("active", "rotating", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of: active, rotating, revoked", field="status")
    if validate is not None and not isinstance(validate, bool):
        return _err("VALIDATION_ERROR", "validate must be a boolean", field="validate")

    workspaces = _load("workspaces.json")
    creds = _load("api_credentials.json")
    if not isinstance(workspaces, list):
        workspaces = []
    if not isinstance(creds, list):
        creds = []

    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == workspace_id:
            ws = w
            break
    if ws is None:
        return _err("NOT_FOUND", "workspace not found", workspace_id=workspace_id)

    # If validate requested: offline datastore cannot call Datadog; accept keys and mark validated now.
    last_validated_at = now_iso if validate else None

    # Fingerprint: non-secret deterministic
    fp = hashlib.sha256((api_key + ":" + app_key).encode("utf-8")).hexdigest()[:16]

    # Enforce unique(key_fingerprint, workspace_id)
    for c in creds:
        if not isinstance(c, dict):
            continue
        if c.get("workspace_id") == workspace_id and c.get("key_fingerprint") == fp:
            # idempotent upsert: update existing row secrets/status if allowed
            target = c
            break
    else:
        target = None

    # Enforce single active per workspace ONLY when promoting to active and there is a different active record.
    if status == "active":
        for c in creds:
            if not isinstance(c, dict):
                continue
            if c.get("workspace_id") == workspace_id and c.get("status") == "active":
                if target is None or c.get("id") != target.get("id"):
                    return _err("CONFLICT", "an active credential already exists for this workspace",
                                workspace_id=workspace_id, active_api_credentials_id=c.get("id"))

    if target is None:
        cred_id = "ddcred_" + uuid.uuid4().hex.upper()[:22]
        row = {
            "id": cred_id,
            "workspace_id": workspace_id,
            "auth_type": auth_type,
            "api_key_ciphertext": api_key,   # stored "encrypted" placeholder; must not require plaintext verification elsewhere
            "app_key_ciphertext": app_key,
            "key_fingerprint": fp,
            "status": status,
            "last_validated_at": last_validated_at,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        creds.append(row)
        _save("api_credentials.json", creds)
        safe = {k: v for k, v in row.items() if k not in ("api_key_ciphertext", "app_key_ciphertext")}
        return {"api_credentials": safe}

    # Update existing target (mutation must have effect)
    changed = False
    if target.get("auth_type") != auth_type:
        target["auth_type"] = auth_type
        changed = True
    if target.get("api_key_ciphertext") != api_key:
        target["api_key_ciphertext"] = api_key
        changed = True
    if target.get("app_key_ciphertext") != app_key:
        target["app_key_ciphertext"] = app_key
        changed = True
    if target.get("key_fingerprint") != fp:
        # should not happen since selected by fp, but keep consistent
        target["key_fingerprint"] = fp
        changed = True
    if status != target.get("status"):
        # must follow lifecycle transitions
        transitions = {"active": ["rotating", "revoked"], "rotating": ["active", "revoked"], "revoked": []}
        cur = target.get("status")
        if cur != status and status not in transitions.get(cur, []):
            return _err("INVALID_TRANSITION", "invalid api_credentials status transition", from_status=cur, to_status=status)
        target["status"] = status
        changed = True
    if validate and last_validated_at is not None and last_validated_at != target.get("last_validated_at"):
        target["last_validated_at"] = last_validated_at
        changed = True

    if not changed:
        return _err("VALIDATION_ERROR", "no changes requested")

    target["updated_at"] = now_iso
    _save("api_credentials.json", creds)
    safe = {k: v for k, v in target.items() if k not in ("api_key_ciphertext", "app_key_ciphertext")}
    return {"api_credentials": safe}

def update_api_credentials_status(workspace_id, api_credentials_id, status, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0064000" if __import__("os").path.isdir("./environment_mix/0064000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now.isoformat().replace("+00:00", "Z")

    if not isinstance(workspace_id, str) or not re.match(r"^ddw_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id must match ^ddw_[0-9A-Z]{18,}$", field="workspace_id")

    if not isinstance(api_credentials_id, str) or not api_credentials_id.strip():
        return _err("VALIDATION_ERROR", "api_credentials_id must be a non-empty string", field="api_credentials_id")
    api_credentials_id = api_credentials_id.strip()

    if not isinstance(status, str) or status not in ("active", "rotating", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of: active, rotating, revoked", field="status")

    workspaces = _load("workspaces.json")
    creds = _load("api_credentials.json")
    request_logs = _load("request_logs.json")  # optional
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(creds, list): creds = []
    request_logs_exists = os.path.exists(os.path.join(_DB, "request_logs.json"))
    if not isinstance(request_logs, list): request_logs = []

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        if request_logs_exists:
            request_logs.append({
                "id": f"ddrl_{os.urandom(8).hex().upper()}",
                "timestamp": now_iso,
                "endpoint": "update-api-credentials-status",
                "workspace_id": workspace_id,
                "credential_id": None,
                "status": "error",
                "error_code": "NOT_FOUND",
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "workspace not found", workspace_id=workspace_id)

    # Resolve credential record:
    # accept exact stored id; additionally accept tool-specified ^ddc_... by suffix match against stored ddcred_...
    rec_idx = None
    for i, c in enumerate(creds):
        if not isinstance(c, dict):
            continue
        if c.get("workspace_id") == workspace_id and c.get("id") == api_credentials_id:
            rec_idx = i
            break
    if rec_idx is None and re.match(r"^ddc_[0-9A-Z]{18,}$", api_credentials_id):
        suffix = api_credentials_id.split("_", 1)[1]
        for i, c in enumerate(creds):
            if not isinstance(c, dict):
                continue
            cid = c.get("id") or ""
            if c.get("workspace_id") == workspace_id and isinstance(cid, str) and "_" in cid and cid.split("_", 1)[1] == suffix:
                rec_idx = i
                break

    if rec_idx is None:
        if request_logs_exists:
            request_logs.append({
                "id": f"ddrl_{os.urandom(8).hex().upper()}",
                "timestamp": now_iso,
                "endpoint": "update-api-credentials-status",
                "workspace_id": workspace_id,
                "credential_id": api_credentials_id,
                "status": "error",
                "error_code": "NOT_FOUND",
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "api_credentials record not found", workspace_id=workspace_id, api_credentials_id=api_credentials_id)

    rec = creds[rec_idx]
    cur = rec.get("status")

    transitions = {"active": ["rotating", "revoked"], "rotating": ["active", "revoked"], "revoked": []}
    if cur not in transitions:
        return _err("VALIDATION_ERROR", "api_credentials has invalid current status", api_credentials_id=rec.get("id"), current=cur)

    # Idempotent: if already in desired status, persist updated_at and return.
    if status == cur:
        rec["updated_at"] = now_iso
        creds[rec_idx] = rec
        _save("api_credentials.json", creds)
        if request_logs_exists:
            request_logs.append({
                "id": f"ddrl_{os.urandom(8).hex().upper()}",
                "timestamp": now_iso,
                "endpoint": "update-api-credentials-status",
                "workspace_id": workspace_id,
                "credential_id": rec.get("id"),
                "status": "ok",
                "error_code": None,
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("request_logs.json", request_logs)
        return {"api_credentials": rec, "changed": False}

    if status not in transitions[cur]:
        return _err("INVALID_TRANSITION", f"Illegal status transition: {cur} -> {status}", workspace_id=workspace_id, api_credentials_id=rec.get("id"), from_status=cur, to_status=status)

    # Enforce single-active per workspace when promoting to active
    if status == "active":
        for c in creds:
            if not isinstance(c, dict):
                continue
            if c.get("workspace_id") == workspace_id and c.get("status") == "active" and c.get("id") != rec.get("id"):
                return _err("CONFLICT", "Another credential is already active for this workspace. Revoke/rotate it first.", workspace_id=workspace_id, api_credentials_id=rec.get("id"), active_api_credentials_id=c.get("id"))

    # Apply transition
    rec["status"] = status
    rec["updated_at"] = now_iso
    if status == "active":
        rec["last_validated_at"] = rec.get("last_validated_at") or now_iso
    creds[rec_idx] = rec

    _save("api_credentials.json", creds)

    if request_logs_exists:
        request_logs.append({
            "id": f"ddrl_{os.urandom(8).hex().upper()}",
            "timestamp": now_iso,
            "endpoint": "update-api-credentials-status",
            "workspace_id": workspace_id,
            "credential_id": rec.get("id"),
            "status": "ok",
            "error_code": None,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", request_logs)

    return {"api_credentials": rec, "changed": True}
